#pragma once

#include <stdbool.h>

/* Square-wave output for a buzzer, generated by an RMT channel that repeats a
 * two-symbol buffer forever. Passive buzzers need a tone in the audio range and
 * get their loudness from the duty cycle; active buzzers ignore the tone and are
 * better driven with a high frequency so only the average current is audible.
 *
 *   BEEP <pin> <freq_hz> <duty_pct>   start / retune (duty 0 stops)
 *   BEEP 0                            stop
 *   BEEP?                             read back the current setting */

void burst_beep_init(void);

/* True when this module owns the line (answered or rejected). */
bool burst_beep_command(const char *line);

/* Pin currently driven by the buzzer, or -1 when silent. */
int burst_beep_owned_pin(void);

/* Stop a sounding tone, if any. The serial layer calls this when the client
 * releases the receiver or loses its lease, so a vanished client cannot leave
 * the buzzer running. Silent when nothing is sounding. */
void burst_beep_silence(void);
